import pandas as pd
import matplotlib.pyplot as plt

# Load the data generated by your C++ engine
data = pd.read_csv('data/simulation_results.csv')

plt.figure(figsize=(10, 6))

# Plotting ATP and HMGB1 release [cite: 185]
plt.plot(data['Hour'], data['ATP'], label='ATP (Necrotic Marker)', color='red', linewidth=2)
plt.plot(data['Hour'], data['HMGB1'], label='HMGB1 (DAMP)', color='blue', linestyle='--')

plt.title('NIR-PIT Induced DAMP Release (40 J/cm²)')
plt.xlabel('Time Post-Irradiation (Hours)')
plt.ylabel('Concentration (Relative Units)')
plt.grid(True, alpha=0.3)
plt.legend()

# Save the plot for your GitHub README
plt.savefig('data/icd_plot.png')
